mapper.select:
SELECT uvpn.start_time , uvpn.end_time , uvpn.videoplay_id , uvpn.id, uvp.user_id as userId FROM gc_user_video_plays_node uvpn LEFT JOIN gc_user_video_play uvp on uvp.id = uvpn. videoplay_id WHERE uvp.user_id in
#{userId}
and uvp.video_id in
#{videoId}
and uvp.master_id = #{masterId}

select * from  gc_user_video_plays_node n left join gc_user_video_play p on
 p.id=n.videoplay_id where  p.user_id=#{userId} and p.master_id=#{masterId} and p.video_id=#{vid}
 order by n.update_time asc limit 1
